-- Seeded system bank-file templates (configuration, not code). Workspaces can copy and edit them.
-- The bulk-upload layout is a PLACEHOLDER: verify against your bank's latest bulk-upload template.
insert into public.bank_templates (key, name, config, is_system)
values
  ('bulk_placeholder', 'Bank bulk upload (placeholder — verify against your bank''s latest template)', '{"key":"bulk_placeholder","name":"Bank bulk upload (placeholder — verify against your bank''s latest template)","isPlaceholder":true,"notes":"Placeholder layout modelled on a typical corporate net-banking bulk payment file. Verify column order, mode codes and limits against your bank''s own bulk-upload template before uploading.","version":1,"fileType":"csv","delimiter":",","includeHeader":true,"lineEnding":"CRLF","trailingNewline":true,"quote":"auto","bom":false,"sheetName":"Payments","columns":[{"header":"Payment Mode","field":"paymentMode"},{"header":"Beneficiary Name","field":"beneficiaryName"},{"header":"Beneficiary Account No","field":"accountNumber","maxLength":18},{"header":"IFSC","field":"ifsc","maxLength":11},{"header":"Amount","field":"amount"},{"header":"Debit Account No","field":"debitAccount","maxLength":18},{"header":"Value Date","field":"valueDate"},{"header":"Remarks/Narration","field":"remarks"},{"header":"Beneficiary Email","field":"email","maxLength":50},{"header":"Beneficiary Mobile","field":"phone","maxLength":10}],"formats":{"dateFormat":"DD/MM/YYYY","amountDecimals":2},"text":{"allowedChars":"A-Za-z0-9 .\\-/","maxNameLength":35,"maxRemarksLength":30,"uppercase":false},"paymentModeRule":{"rtgsMinPaise":20000000,"defaultMode":"NEFT","sameBankMode":"FT","allowRtgs":true,"allowImps":false,"impsMaxPaise":50000000,"modeCodes":{"NEFT":"N","RTGS":"R","IMPS":"M","FT":"I"}},"maxRowsPerFile":500,"newPayeesAllowed":"unknown"}'::jsonb, true),
  ('generic_csv', 'Generic CSV', '{"key":"generic_csv","name":"Generic CSV","isPlaceholder":false,"notes":"Neutral layout for banks that let you map columns during upload.","version":1,"fileType":"csv","delimiter":",","includeHeader":true,"lineEnding":"CRLF","trailingNewline":true,"quote":"auto","bom":false,"sheetName":"Payments","columns":[{"header":"Sr No","field":"serial"},{"header":"Payment Mode","field":"paymentMode"},{"header":"Beneficiary Name","field":"beneficiaryName"},{"header":"Account Number","field":"accountNumber"},{"header":"IFSC","field":"ifsc"},{"header":"Amount","field":"amount"},{"header":"Debit Account","field":"debitAccount"},{"header":"Value Date","field":"valueDate"},{"header":"Remarks","field":"remarks"},{"header":"Email","field":"email"},{"header":"Phone","field":"phone"}],"formats":{"dateFormat":"DD-MM-YYYY","amountDecimals":2},"text":{"allowedChars":"A-Za-z0-9 .,\\-/&()","maxNameLength":50,"maxRemarksLength":60,"uppercase":false},"paymentModeRule":{"rtgsMinPaise":20000000,"defaultMode":"NEFT","allowRtgs":true,"allowImps":true,"impsMaxPaise":50000000,"modeCodes":{"NEFT":"NEFT","RTGS":"RTGS","IMPS":"IMPS","FT":"FT"}},"maxRowsPerFile":5000,"newPayeesAllowed":"unknown"}'::jsonb, true)
on conflict (key) where workspace_id is null do update
  set name = excluded.name, config = excluded.config, updated_at = now();
